
-- Deterministic internal editorial plans for UAlg 1812 (Faro, 2026/27).
-- These are NOT generated by AI or validated by lecturers. Keep as private draft.
INSERT INTO facodi.generated_structures(
 id,root_object_id,structure_type,status,prompt,result,generated_by)
SELECT md5('facodi:ctesp1812:study-path:'||u.code)::uuid,
 u.learning_object_id,'module','draft',
 jsonb_build_object('editorial_kind','uc_study_path','version','2026-11-14',
  'source','facodi.curricular_units.metadata.study_topics',
  'official_course_code','1812','unit_code',u.code,
  'mode','deterministic_from_real_curriculum_and_sources',
  'teacher_review_required',true,'ai_model_executed',false),
 jsonb_build_object('title',u.title,
  'code',u.code,'year',u.year,'semester',u.semester,'ects',u.ects,
  'topics',(SELECT coalesce(jsonb_agg(jsonb_build_object(
    'order',topic.ord,'title',topic.name,
    'activity',CASE topic.ord WHEN 1 THEN 'Ler conceitos e anotar termos'
      WHEN 2 THEN 'Relacionar os conceitos com exemplos práticos'
      ELSE 'Aplicar os conceitos num exercício independente' END,
    'editorial_status','draft_needs_teacher_review') ORDER BY topic.ord),'[]'::jsonb)
    FROM jsonb_array_elements_text(u.metadata->'study_topics')
      WITH ORDINALITY topic(name,ord)),
  'approved_video_links',(SELECT count(*) FROM facodi.unit_videos uv
    WHERE uv.curricular_unit_id=u.id AND uv.metadata->>'review_status'='approved'),
  'approved_reading_links',(SELECT count(*) FROM facodi.learning_object_relations r
    WHERE r.parent_object_id=u.learning_object_id
      AND r.created_by_mechanism='verified_external_reading_curation'),
  'resources',(SELECT coalesce(jsonb_agg(sub.source_url ORDER BY sub.position),'[]'::jsonb)
    FROM (SELECT lo.source_url,r.position
      FROM facodi.learning_object_relations r
      JOIN facodi.learning_objects lo ON lo.id=r.child_object_id
      WHERE r.parent_object_id=u.learning_object_id
        AND r.created_by_mechanism='verified_external_reading_curation'
        AND lo.published AND lo.status='active'
      ORDER BY r.position LIMIT 10) sub),
  'disclaimer','Estrutura pedagógica FACODI provisória. Não é a ficha oficial da UC, nem prova de aprendizagem do estudante.'),
 'facodi_deterministic_editorial_blueprint'
FROM facodi.curricular_units u
JOIN facodi.courses c ON c.id=u.course_id
WHERE c.code='CTESP-STI'
AND c.published=true AND c.status='active'
AND u.status='active' AND u.published=true
AND u.learning_object_id IS NOT NULL
ON CONFLICT(id) DO NOTHING;

INSERT INTO facodi.generated_structures(
 id,root_object_id,structure_type,status,prompt,result,generated_by)
SELECT md5('facodi:ctesp1812:course-map')::uuid,
 c.learning_object_id,'curriculum_mapping','draft',
 jsonb_build_object('editorial_kind','course_map','source','ualg_2026_27_official_plan',
  'official_course_id','1812','year','2026/27',
  'mode','deterministic_from_published_curriculum',
  'ai_model_executed',false,'teacher_review_required',true),
 jsonb_build_object('official_title',c.title,'official_url',c.plan_url,
  'ects_total',c.ects_total,'duration_semesters',c.duration_semesters,
  'units',(SELECT coalesce(jsonb_agg(jsonb_build_object(
    'code',u.code,'title',u.title,'ects',u.ects,
    'year',u.year,'semester',u.semester,'unit_id',u.id,
    'has_external_material',(EXISTS(
      SELECT 1 FROM facodi.learning_object_relations r
      WHERE r.parent_object_id=u.learning_object_id AND r.created_by_mechanism='verified_external_reading_curation')))
    ORDER BY u.semester,u.position),'[]'::jsonb)
    FROM facodi.curricular_units u WHERE u.course_id=c.id
    AND u.status='active' AND u.published),
  'note','Estrutura oficial de 120 ECTS; descrições dos conteúdos de estudo são editoriais.'),
 'facodi_deterministic_editorial_blueprint'
FROM facodi.courses c
WHERE c.code='CTESP-STI' AND c.published AND c.status='active'
AND c.learning_object_id IS NOT NULL
ON CONFLICT(id) DO NOTHING;

DO $validate$ BEGIN
 IF (SELECT count(*) FROM facodi.generated_structures g
  WHERE g.generated_by='facodi_deterministic_editorial_blueprint'
  AND g.root_object_id IN
    (SELECT u.learning_object_id FROM facodi.curricular_units u
      WHERE u.course_id=md5('facodi:ualg:1812:course:record')::uuid)
  AND g.structure_type='module')<>17
 THEN RAISE EXCEPTION 'Expected 17 private editorial study paths'; END IF;
 IF (SELECT count(*) FROM facodi.generated_structures
  WHERE id=md5('facodi:ctesp1812:course-map')::uuid)<>1
 THEN RAISE EXCEPTION 'Missing internal course map'; END IF;
END $validate$;